def state_abstraction(grid):
    # Create an empty dictionary to store the groups
    groups = {}

    # Iterate over each cell in the grid
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            # If the cell is not the goal and has not been visited before
            if grid[i][j] != 52 and (i, j) not in groups:
                # Create a new group for this cell
                group = set()
                stack = [(i, j)]

                # Perform a depth-first search to find all adjacent cells
                while stack:
                    x, y = stack.pop()
                    group.add((x, y))

                    # Check all four directions (up, down, left, right)
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy

                        # If the adjacent cell is within the grid boundaries
                        if 0 <= nx < len(grid) and 0 <= ny < len(grid[nx]):
                            # Add it to the group if it's not the goal or has not been visited before
                            if grid[nx][ny] != 52 and (nx, ny) not in groups:
                                stack.append((nx, ny))

                # Store the group in the dictionary
                groups[(i, j)] = group

    # Convert the groups back into a list of lists for each state
    grouped_states = []
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] != 52:
                adjacent_states = []
                for x, y in groups[(i, j)]:
                    adjacent_states.append((x * len(grid[x]) + y) * 4 + int(i == x and j == y))
                grouped_states.append(adjacent_states)

    return grouped_states
